CREATE TABLE saf_issue (
 id BIGINT NOT NULL,tenant_id BIGINT NOT NULL,organization_id BIGINT NOT NULL,project_id BIGINT NOT NULL,supplier_id BIGINT NOT NULL,issue_no VARCHAR(64) NOT NULL,title VARCHAR(200) NOT NULL,category VARCHAR(32) NOT NULL,severity VARCHAR(16) NOT NULL,description VARCHAR(2000) NOT NULL,location VARCHAR(300) NULL,discovered_at DATETIME(3) NOT NULL,deadline DATE NOT NULL,responsible_user_id BIGINT NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'OPEN',rectification_note VARCHAR(2000) NULL,rectification_file_id BIGINT NULL,submitted_at DATETIME(3) NULL,verification_result VARCHAR(16) NULL,verification_comment VARCHAR(1000) NULL,verified_by BIGINT NULL,verified_at DATETIME(3) NULL,created_by BIGINT NOT NULL,updated_by BIGINT NOT NULL,version INT NOT NULL DEFAULT 0,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),PRIMARY KEY(id),UNIQUE KEY uk_saf_issue_no(tenant_id,issue_no),KEY idx_saf_issue_project(tenant_id,project_id,status),KEY idx_saf_issue_supplier(tenant_id,supplier_id,status),KEY idx_saf_issue_deadline(tenant_id,status,deadline),CONSTRAINT fk_saf_issue_tenant FOREIGN KEY(tenant_id) REFERENCES iam_tenant(id),CONSTRAINT fk_saf_issue_org FOREIGN KEY(organization_id) REFERENCES iam_organization(id),CONSTRAINT fk_saf_issue_project FOREIGN KEY(project_id) REFERENCES prj_project(id),CONSTRAINT fk_saf_issue_supplier FOREIGN KEY(supplier_id) REFERENCES sup_supplier(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
